"""Every rounding rule of meterbill, in one place.

All decimal rounding here is exact integer arithmetic: nothing reads or
depends on the decimal context.
"""

from __future__ import annotations

import math
from decimal import Decimal

CENT = Decimal("0.01")
HALF_UP = "half_up"
HALF_EVEN = "half_even"
DOWN = "down"

_METHODS = (HALF_UP, HALF_EVEN, DOWN)


def _build(sign: int, coef: int, exp: int) -> Decimal:
    return Decimal((sign, tuple(int(d) for d in str(coef)), exp))


def _parts(d: Decimal):
    sign, digits, exp = d.as_tuple()
    coef = 0
    for digit in digits:
        coef = coef * 10 + digit
    return sign, coef, exp


def _add(a: Decimal, b: Decimal) -> Decimal:
    """Exact sum, with the sign of a zero as ordinary (non-floor) addition gives it."""
    sa, ca, ea = _parts(a)
    sb, cb, eb = _parts(b)
    exp = min(ea, eb)
    x = ca * 10 ** (ea - exp) * (-1 if sa else 1)
    y = cb * 10 ** (eb - exp) * (-1 if sb else 1)
    total = x + y
    if total == 0:
        return _build(1 if (sa and sb) else 0, 0, exp)
    return _build(1 if total < 0 else 0, abs(total), exp)


def _neg(d: Decimal) -> Decimal:
    sign, digits, exp = d.as_tuple()
    return Decimal((0 if sign else 1, digits, exp))


def _check(value, step, method) -> None:
    if not isinstance(value, Decimal) or not isinstance(step, Decimal):
        raise TypeError("value and step must be Decimal")
    if method not in _METHODS:
        raise ValueError(f"unknown rounding method {method!r}")
    if not step.is_finite() or step <= 0:
        raise ValueError("step must be positive")
    if not value.is_finite():
        raise ValueError("value must be finite")


def round_amount(value: Decimal, step: Decimal, method: str) -> Decimal:
    """The multiple of `step` nearest to `value`; `method` rules ties and direction."""
    _check(value, step, method)
    sign, coef, exp = _parts(value)
    _, step_coef, step_exp = _parts(step)
    if exp >= step_exp:
        num, den = coef * 10 ** (exp - step_exp), step_coef
    else:
        num, den = coef, step_coef * 10 ** (step_exp - exp)
    q, r = divmod(num, den)
    if method == HALF_UP:
        if 2 * r >= den:
            q += 1
    elif method == HALF_EVEN:
        if 2 * r > den or (2 * r == den and q % 2 == 1):
            q += 1
    return _build(sign, q * step_coef, step_exp)


def allocate(amounts: list[Decimal], step: Decimal) -> list[Decimal]:
    """One part per amount, adding up to the rounded sum of the amounts.

    Each amount is cut down to `step`; what the cuts lost against the
    half-up rounded total goes on the last amount that is not zero.
    """
    parts = [round_amount(a, step, DOWN) for a in amounts]
    exact = Decimal("0")
    for a in amounts:
        exact = _add(exact, a)
    whole = round_amount(exact, step, HALF_UP)
    cut = Decimal((0, (0,), _parts(step)[2]))
    for p in parts:
        cut = _add(cut, p)
    rest = _add(whole, _neg(cut))
    for i in range(len(parts) - 1, -1, -1):
        if amounts[i] != 0:
            parts[i] = _add(parts[i], rest)
            break
    return parts


def legacy_cents(value: float, places: int = 2) -> float:
    """A float as the old customer system settled it: binary floating point, half up."""
    scale = 10**places
    return math.floor(value * scale + 0.5) / scale


def fixed(value: float | Decimal, places: int, method: str = HALF_EVEN) -> str:
    """`value` written with `places` digits after the point."""
    if isinstance(places, bool) or not isinstance(places, int):
        raise TypeError("places must be an int")
    if places < 0:
        raise ValueError("places must not be negative")
    if isinstance(value, Decimal):
        step = _build(0, 1, -places)
        sign, coef, _ = _parts(round_amount(value, step, method))
        digits = str(coef).rjust(places + 1, "0")
        text = digits[: len(digits) - places]
        if places:
            text += "." + digits[len(digits) - places :]
        return ("-" if sign else "") + text
    if isinstance(value, float):
        if method != HALF_EVEN:
            raise ValueError("a float is only written half-even")
        return format(value, f".{places}f")
    raise TypeError("value must be a float or a Decimal")
EOF

