cd /app; python -m unittest discover -s tests -t . 2>&1 | tail -3
cat > /tmp/diff.py <<'EOF'
import subprocess, random, json, os, glob, tempfile, sys
def run(root, args):
    p=subprocess.run([sys.executable,'-m','meterbill']+args,cwd=root,capture_output=True,text=True)
    return p.returncode,p.stdout,p.stderr
random.seed(5)
tmp=tempfile.mkdtemp()
tar=json.load(open('/app/meterbill/data/tariffs.json'))
names=list(tar['tariffs'])
accts=[]
for i in range(150):
    d={"account":f"X{i}","tariff":random.choice(names),
      "period":{"start":"2026-03-01","end":"2026-03-%02d"%random.randint(1,31)},
      "readings":[{"meter":"M","kwh":str(round(random.uniform(0,900),random.choice([0,1,2,3])))}],
      "credits":[{"ref":"c","amount":random.choice([-4.25,2.675,1.005,0.125,-0.005,1e-9,random.uniform(-9,9)])} for _ in range(random.randint(0,3))]}
    if random.random()<.5:
        d["standing"]=[{"from":"2026-03-01","to":"2026-03-%02d"%random.randint(1,10),"rate":random.choice(["0.4110","0.0333","-0.0155","0","0.00005","0.1255"])},{"from":"2026-03-11","to":"2026-03-20","rate":random.choice(["0.0050","0.3335","0"])}]
    json.dump(d,open(f"{tmp}/a{i:03}.json","w")); accts.append(f"{tmp}/a{i:03}.json")
bad=0
cmds=[]
for a in accts:
    for f in ("text","csv","json"): cmds.append(["bill",a,"--format",f])
cmds+= [["batch",tmp],["batch",tmp,"--format","csv"],["tariffs"],["batch","/app/samples/accounts"]]
for t in names:
    for _ in range(15):
        cmds.append(["quote",t,str(round(random.uniform(0,900),random.choice([0,1,2,3,4]))),str(random.randint(1,40))])
        cmds.append(["quote",t,"1.005","3","--format","json"])
for c in cmds:
    if run('/tmp/orig',c)!=run('/app',c): bad+=1; print("DIFF",c)
print(len(cmds),"bad",bad)
EOF
python /tmp/diff.py

